// Module 5 — Emerging & Future Technologies
// Bloom's-aligned MCQs. Each topic follows the progression:
// Q1-Q2 Remember · Q3-Q4 Understand · Q5-Q7 Apply · Q8 Analyze · Q9 Evaluate · Q10 Create
// All options are roughly equal length (distractors may be longer, never shorter than the correct answer).

import type { Question } from "./module1-mcq";

export const mcqData: Record<number, Question[]> = {
  // ─── Topic 1: Artificial Intelligence (simple, school-level) ───
  1: [
    { q: "What is Artificial Intelligence, in simple words?", opts: ["Software that can do things that usually need a human brain, like face or speech recognition", "A metal robot with arms and legs that does chores around a house or a lecture classroom every day", "A new shiny phone case that makes older phones much faster than they normally would be", "A special cable that connects a computer to the internet so it can download apps quickly"], ans: 0, why: "AI is software that can do tasks we used to think needed a human brain \u2014 recognising faces, understanding speech, guessing what you want. It doesn\u2019t have to be a robot. A phone case or cable is hardware, not AI.", bloom: "remember" },
    { q: "Which of these is an example of AI that you probably use every day?", opts: ["A normal paper notebook where you write down your school homework each evening carefully", "A plastic calculator that adds and subtracts two numbers using only its hardware buttons", "TikTok\u2019s \u201cFor You\u201d page picking videos it thinks you\u2019ll like from millions of videos", "A clock on the wall showing the time in hours and minutes using two long black hands"], ans: 2, why: "TikTok uses AI to pick videos you\u2019re likely to watch, based on what you liked before. A paper notebook, a plastic calculator, and an analogue clock do not learn or adapt \u2014 they are not AI.", bloom: "remember" },
    { q: "Why is today\u2019s AI called \u201cnarrow\u201d?", opts: ["Because it runs on thin computers that are made of very narrow pieces of plastic and metal parts", "Because each AI is built for only one task and cannot switch to other tasks on its own", "Because only a small number of people are allowed to use it in any country in the whole world", "Because it stops working completely whenever the room is too hot or too cold to use it"], ans: 1, why: "\u201cNarrow\u201d means each AI is good at ONE task. Siri can answer questions but cannot drive a car. Netflix picks shows but cannot write emails. It has nothing to do with the shape of the computer or who uses it.", bloom: "understand" },
    { q: "How is an AI model different from a normal program?", opts: ["A normal program costs more money to build than any other kind of software on the market today", "A normal program cannot be used on a phone, while AI can be used on any kind of smartphone app", "A normal program follows rules a human wrote, while AI learns patterns from lots of examples", "A normal program only works at night while AI works during the day when there is bright sunlight"], ans: 2, why: "A normal program follows rules a human wrote step by step. AI learns from many examples and finds its own patterns. Cost, device, or time of day have nothing to do with the difference.", bloom: "understand" },
    { q: "You open Yandex Taxi and it shows you an arrival time of \u201c4 minutes.\u201d How did it guess?", opts: ["AI looked at traffic and past rides on that road to predict how long the ride should take", "A human worker at Yandex sat at a desk and typed \u201c4 minutes\u201d by hand for every single rider", "The app picked any random number between one minute and ten minutes just to show something", "Your phone\u2019s battery level decides the time \u2014 a full battery always shows a short arrival time"], ans: 0, why: "Yandex uses AI that has learned from millions of past rides and live traffic \u2014 that is how it can guess a good estimate fast. There is no human typing it, no random number, and battery level is not involved.", bloom: "apply" },
    { q: "Your grandmother\u2019s phone suddenly starts showing many strange emails about winning lottery prizes. How does Gmail stop most of these from reaching her inbox?", opts: ["Gmail shuts down her phone completely until she deletes every email in her account one by one herself", "Gmail uses AI that learned from millions of spam examples to spot and block new spam", "Gmail sends each email to her nearest family member first and asks them to decide what to do about it", "Gmail prints each suspicious email on paper and posts it to her home address to check later"], ans: 1, why: "Gmail\u2019s AI learned what spam looks like from huge numbers of examples and user \u201cspam\u201d clicks. It can spot new spam your grandmother has never seen. The other options are not how any email app works.", bloom: "apply" },
    { q: "You want your Instagram \u201cFor You\u201d page to show more football content. What actually makes the AI change its suggestions?", opts: ["Writing a long private message to Instagram headquarters asking them to show you football videos next time", "Buying a new and more expensive phone so that Instagram will start treating you as a real football fan", "Printing a photo of a football and holding it in front of your phone camera for a few minutes each day", "Watching football videos fully, liking them, following football pages, and searching football topics"], ans: 3, why: "AI in Instagram learns from what you do \u2014 what you watch, like, follow, and search. That is how it slowly shifts your feed. Writing messages, buying phones, or showing photos to the camera won\u2019t change the algorithm.", bloom: "apply" },
    { q: "An AI tool for choosing workers at a Tashkent company keeps picking mostly men, even though many women also apply. What probably went wrong?", opts: ["The AI secretly watched the applicants through the laptop camera and then made a completely random decision", "The AI picked workers based on the colour of the clothes they wore in their job application photos", "The AI stopped working halfway through and just guessed answers based on nothing at all at any point", "The AI learned from old hiring records where mostly men were hired, so it repeats the old pattern"], ans: 3, why: "AI learns from the past. If the past data favoured men, the AI will copy that unfair pattern \u2014 even if nobody told it to. This is called AI bias. It is not about cameras, clothes, or random guesses.", bloom: "analyze" },
    { q: "Your friend says: \u201cAI is always right \u2014 if ChatGPT says something, it must be true.\u201d Is this a good way to use AI?", opts: ["Yes \u2014 ChatGPT has read all the books and is always correct about every single subject in the world", "Yes \u2014 the newest AI tools never make any mistakes and you do not need to check what they say at all", "No \u2014 AI can sound sure of itself but still be wrong, so always check important facts first", "No \u2014 AI is always wrong about every answer it gives, so never use it for any kind of task at all"], ans: 2, why: "AI can sound confident and still be wrong \u2014 this is called a \u201challucination.\u201d Always check important facts with a trusted source. \u201cAlways right\u201d and \u201calways wrong\u201d are both extreme and both incorrect.", bloom: "evaluate" },
    { q: "Design a simple, fair rule for using AI in your ICT classroom so students learn instead of just copying.", opts: ["Ban every use of AI forever and punish any student who even mentions an AI tool in the classroom", "Let students use AI to explain ideas and check grammar, but they must write the final work themselves", "Let students copy and paste any AI answer directly into their homework without reading or checking it all at all", "Ignore the whole AI question and hope the students will decide what is fair on their own each week"], ans: 1, why: "The fair rule is: AI helps you LEARN (explain a concept, check grammar), but you still write the final work yourself. A total ban ignores useful help, and copy-paste means no learning happens. Silence leaves the problem unsolved.", bloom: "create" },
  ],

  // ─── Topic 2: Machine Learning (simple, school-level) ───
  2: [
    { q: "What is Machine Learning, in simple words?", opts: ["When a computer learns from lots of examples instead of following rules a human wrote", "When a computer is physically put inside a washing machine, a dishwasher, or a microwave", "When a new computer learns how to turn itself on for the first time without any help", "When a very old computer is fixed by a technician so it can work for a few extra years"], ans: 0, why: "Machine Learning means the computer looks at lots of examples and finds patterns by itself. It is not about being inside a machine, turning on, or being fixed.", bloom: "remember" },
    { q: "Which of these is an example of Machine Learning at work?", opts: ["A plastic ruler measuring the length of a straight line drawn on a piece of A4 paper at school", "A light bulb turning on when you press the switch on the wall of the living room at home", "Spotify suggesting a song you\u2019ll probably like based on what you listened to last week", "A paper map of Uzbekistan used by a tourist to find the route to Samarkand on a long trip"], ans: 2, why: "Spotify learns from your listening history \u2014 that is ML. A ruler, light switch, or paper map do not learn or adapt. They behave exactly the same every time.", bloom: "remember" },
    { q: "How is Machine Learning different from a normal computer program?", opts: ["Normal programs are always faster and better than ML in every single situation for every task ever", "Normal programs follow rules a human wrote; ML learns rules by itself from many examples", "Normal programs only use the colour red, while ML programs can use many different colours too", "Normal programs were only invented last year, but ML programs have been around for many years"], ans: 1, why: "A normal program follows rules a person wrote step by step. ML takes many examples and finds its own rules. Colour, age, or speed are not what separates the two.", bloom: "understand" },
    { q: "Why does a ML model usually improve when you give it more examples?", opts: ["The examples are secretly the answers the model will be asked about during every single test", "More examples make the computer physically bigger, and bigger computers are always smarter than small ones", "More examples help the model spot more patterns and handle new, unseen cases better", "More examples always make ML worse, so people give it as few examples as possible each time"], ans: 2, why: "More real examples help the model pick up genuine patterns and handle new situations. Examples aren\u2019t the exact test, they don\u2019t change the computer\u2019s size, and \u201cfewer is better\u201d is wrong.", bloom: "understand" },
    { q: "Your Telegram auto-translate gets better at Uzbek over time. Why might that be?", opts: ["Telegram hires hundreds of Uzbek workers to translate every single new message by hand each day", "ML learns from more Uzbek messages and corrections, so translations become smoother over time", "Your phone secretly listens to family speaking at home and memorises every Uzbek word it hears", "Telegram randomly changes its translations every day and sometimes the random choice is just better"], ans: 1, why: "Translation AI improves by learning from more real examples. Humans translating every message won\u2019t scale. Secret listening and daily randomness are not how this works.", bloom: "apply" },
    { q: "TikTok shows your little brother lots of PUBG clips after he watched three on your account. How does the app decide?", opts: ["TikTok calls the family\u2019s internet provider and asks them what kind of videos the household likes", "The app reads the name of the phone\u2019s owner and decides which videos to show them each day", "TikTok always shows exactly the same videos to every user \u2014 the suggestions never really change at all", "ML tracks which videos are watched fully and liked, then picks similar videos to show next"], ans: 3, why: "TikTok\u2019s ML learns from watch time and likes, then finds similar clips. It does not phone providers, read phone owner names, or show everyone the same feed.", bloom: "apply" },
    { q: "A bank in Tashkent wants to catch card fraud faster. Which job fits machine learning well?", opts: ["Printing a single one-page paper report at the end of each month for every branch manager team", "Choosing a new bank office location in a good street of central Tashkent near many customers", "Counting the number of coins stored in the physical safe of the bank’s head office each morning", "Spotting unusual patterns in card activity that don’t match a customer’s normal spending habits"], ans: 3, why: "ML is great at finding unusual patterns in huge amounts of data \u2014 exactly the fraud-detection job. Printing monthly papers, counting coins, and picking office locations are not ML tasks.", bloom: "apply" },
    { q: "A face-unlock works great indoors but fails often outdoors in bright sun. What probably went wrong?", opts: ["Your face becomes unrecognisable to every living person, including your own family, in bright sunlight", "Bright sun damages the phone camera every time you go outside, which is why face unlock stops working", "It was trained mostly on indoor photos, so it struggles with very different outdoor lighting", "The phone gets too warm in the sunlight, so it simply refuses to unlock until the evening comes later"], ans: 2, why: "If training data was mostly indoors, the model struggles with new lighting. Your face doesn\u2019t truly become unrecognisable, the camera isn\u2019t sun-damaged, and a warm phone doesn\u2019t refuse face unlock by design.", bloom: "analyze" },
    { q: "A student says: \u201cMore data always makes an ML model better \u2014 quality doesn\u2019t matter.\u201d Is this a good rule?", opts: ["Yes \u2014 ML models love every kind of data equally no matter how messy or how wrong it might be", "Yes \u2014 data quality is not a real thing in machine learning, it is only a made-up marketing phrase", "No \u2014 bad or unfair data can teach the model the wrong patterns, so quality really does matter", "No \u2014 more data always breaks ML models, and the best models are the ones trained on no data"], ans: 2, why: "Quality matters. Bad or biased data teaches the wrong lessons. \u201cMore is always better regardless of quality\u201d is wrong, and \u201cno data at all\u201d isn\u2019t ML.", bloom: "evaluate" },
    { q: "Design a simple ML idea for a Tashkent bakery that wants to bake the right number of loaves each morning.", opts: ["Bake the exact same number of loaves every single day of the year without checking any patterns at all", "Train a model on past sales, weather, and day of week to predict tomorrow\u2019s demand each morning", "Ask customers walking in at 7 a.m. to vote on how many loaves the bakery should bake that morning", "Only bake loaves on days when the weather is sunny and never bake any bread on any rainy day at all"], ans: 1, why: "ML can learn from past sales, weather, and day-of-week patterns to predict demand \u2014 saving money and waste. Same number daily, 7 a.m. votes, or sunny-day-only baking won\u2019t match real demand.", bloom: "create" },
  ],

  // ─── Topic 3: Data Analytics (simple, school-level) ───
  3: [
    { q: "What is Data Analytics, in simple words?", opts: ["Looking at raw numbers and turning them into useful answers that help people make decisions", "A game on your phone where you collect points by answering simple numerical questions quickly", "Only counting how many people live in Tashkent every year using official government records", "A special type of calculator that is used only by maths teachers in secondary schools across Uzbekistan"], ans: 0, why: "Data analytics means taking raw numbers and making them useful \u2014 so shops, banks, or schools can make better choices. It\u2019s not a phone game, a population count, or a special calculator.", bloom: "remember" },
    { q: "Which of these is a simple example of data analytics in daily life?", opts: ["A plastic water bottle standing on a table in the school cafeteria during the lunch break today", "Uzum looking at what sold last weekend and putting popular items on the home page on Friday", "A paper textbook sitting on a desk in the university library without being opened all day", "A metal pen lying inside a backpack on the way home from school one Friday afternoon"], ans: 1, why: "Uzum checking sales and using that information is data analytics. A water bottle, a textbook, or a pen sitting there is not data analytics \u2014 no numbers are being used to make a decision.", bloom: "remember" },
    { q: "Which question does the \u201cWhat happened?\u201d type of analytics answer?", opts: ["Looks into the future and tells the exact price of bread next year with full certainty", "Picks a specific action to take, like lowering the price of every product by ten percent today", "Looks at the past \u2014 for example, total sales in March or the number of rides last weekend", "Explains in detail why a business lost customers last year based on many hours of interviews"], ans: 2, why: "\u201cWhat happened\u201d is descriptive \u2014 it summarises the past. \u201cWhat will happen\u201d is predictive, \u201cwhat should we do\u201d is prescriptive, \u201cwhy did it happen\u201d is diagnostic.", bloom: "understand" },
    { q: "Which question does the \u201cWhat should we do?\u201d type of analytics answer?", opts: ["It lists what the sales numbers looked like in each of the last twelve months of the past year", "It suggests a specific action, such as \u201csend more taxi drivers to the metro at 6 p.m. tomorrow\u201d", "It tries to explain why sales fell last quarter using old interviews with many former customers", "It only shows the coldest temperature recorded in Tashkent during the previous month of January"], ans: 1, why: "\u201cWhat should we do?\u201d is prescriptive \u2014 it suggests an action. Listing past months is descriptive, explaining why is diagnostic, and showing only temperature is not prescriptive.", bloom: "understand" },
    { q: "A Payme dashboard shows: \u201cYou spent 2.5 million UZS on food this month.\u201d Which type of analytics is that?", opts: ["\u201cWhat happened\u201d \u2014 it just describes how much was spent in the past month without explaining anything", "\u201cWhy did it happen\u201d \u2014 it gives the exact reason for the spending change compared to the last year", "\u201cWhat should we do\u201d \u2014 it tells you to cut food spending to a much lower amount starting tomorrow", "\u201cWhat will happen\u201d \u2014 it predicts exactly how much money you will likely spend on food again next month"], ans: 0, why: "Showing past spending is descriptive (\u201cwhat happened\u201d). It\u2019s not explaining why, suggesting an action, or forecasting.", bloom: "apply" },
    { q: "Yandex Taxi predicts: \u201cHigh demand near the metro at 6 p.m.\u201d Which type of analytics is this?", opts: ["\u201cWhat happened\u201d \u2014 it just shows how many rides finished yesterday in the metro zone of Tashkent", "\u201cWhy did it happen\u201d \u2014 it explains the exact reason rides went up last Tuesday near the main metro stop", "\u201cWhat should we do\u201d \u2014 it automatically books a taxi for every single rider it thinks will travel later today", "\u201cWhat will happen\u201d \u2014 it uses past rides and times to guess busy zones later today or tomorrow"], ans: 3, why: "Using past patterns to guess the future is predictive (\u201cwhat will happen\u201d). The other three are descriptive, diagnostic, or prescriptive \u2014 not predictive.", bloom: "apply" },
    { q: "A Tashkent bakery sees that sales drop every Wednesday. The manager wants to know WHY. Which type of analytics fits best?", opts: ["Descriptive — it just repeats the sales numbers without saying anything about any possible cause at all", "Prescriptive — it just recommends closing the bakery on Wednesdays without explaining any reason at all", "Predictive — it tries to guess how bad sales will be on every single Wednesday for the rest of the year", "Diagnostic — it looks into reasons like school holidays, weather, or a nearby shop opening that day"], ans: 3, why: "\u201cWhy did this happen?\u201d is diagnostic analytics. Descriptive only describes, predictive forecasts, prescriptive recommends \u2014 none of them answer \u201cwhy.\u201d", bloom: "apply" },
    { q: "A company keeps showing sales are falling, but never asks why. What can go wrong if they skip the \u201cwhy\u201d step?", opts: ["Nothing goes wrong \u2014 the company always recovers automatically next quarter even if they do nothing at all", "The sales number becomes invisible to the managers because not asking why hides numbers from the dashboard", "They know the number but not the reason, so any fix is just a guess and the drop can easily repeat", "The company\u2019s bank account is automatically frozen by the government because they skipped a required step"], ans: 2, why: "Without the \u201cwhy\u201d step, fixes are blind guesses and the drop can repeat. Skipping the question doesn\u2019t hide numbers or freeze bank accounts.", bloom: "analyze" },
    { q: "Your friend says: \u201cDescriptive analytics is enough. Nobody really needs prediction or prescription.\u201d Is this a good view?", opts: ["Yes \u2014 once you know the past, the future decisions always become obvious without any further thought needed", "No \u2014 descriptive shows the past, but bigger value comes when we also forecast and suggest actions", "Yes \u2014 predicting and suggesting actions is too hard for any business person to actually understand today", "No \u2014 only prediction matters, and looking at the past is a complete waste of time for any team ever"], ans: 1, why: "Descriptive is useful but limited. Real business value often comes from predicting what\u2019s next and suggesting an action. \u201cOnly prediction\u201d is also wrong \u2014 they build on each other.", bloom: "evaluate" },
    { q: "Design a simple 4-step analytics plan for a small family caf\u00e9 in Tashkent that wants more customers.", opts: ["Stop collecting any data at all and hope that the caf\u00e9 will magically get busier over the next few months", "Close the caf\u00e9 every Monday without collecting any numbers and just hope the customers come back on Tuesday", "Look at past sales \u2192 find out why quiet days are quiet \u2192 guess busy days \u2192 plan a small offer for slow days", "Raise every menu price by fifty percent without looking at any customer pattern or daily sales data at all"], ans: 2, why: "A good plan walks through all four types: describe (past sales), diagnose (why quiet), predict (busy days), prescribe (promo on slow days). The others ignore data or punish customers.", bloom: "create" },
  ],

  // ─── Topic 4: Cloud Computing (simple, school-level) ───
  // Rewritten for 17-year-old first-time ICT students. No IaaS/PaaS/SaaS,
  // no deployment models — just "what is cloud, why use it, how it helps."
  // Bloom's: Q1-Q2 Remember · Q3-Q4 Understand · Q5-Q7 Apply · Q8 Analyze ·
  // Q9 Evaluate · Q10 Create. Correct answer is never the longest option.
  4: [
    { q: "What is cloud computing, in simple words?", opts: ["Saving your files and running programs on big computers on the internet, not only on your own device", "A special weather-tracking program that predicts rain, snow, and cloud movement using satellite data every hour", "A type of faster Wi-Fi connection that only works outside when there are real clouds visible in the sky", "A new kind of laptop battery that was invented to last much longer than older models on the market today"], ans: 0, why: "Cloud computing means your files and apps live on powerful computers on the internet (called servers), not only on your phone or laptop. You reach them through the internet from any device. The 'cloud' has nothing to do with weather — it's just a word for 'on the internet'.", bloom: "remember" },
    { q: "Which of these is an example of using the cloud in daily life?", opts: ["Writing a note using a pen and paper in your school notebook during a lesson in the classroom", "Copying a file from one folder to another folder on the same laptop's hard drive at home", "Saving photos to Google Photos or iCloud so you can open them from your phone and laptop", "Printing your homework on a home printer before going to school the next morning"], ans: 2, why: "Google Photos and iCloud save your photos on Google's or Apple's cloud computers. That's why you can open the same photo from your phone AND your laptop. A paper note, a print-out, and a folder-to-folder copy all stay on ONE device — that is not cloud.", bloom: "remember" },
    { q: "Why can you open the same Gmail inbox from your phone, your laptop, AND a friend's computer?", opts: ["Your phone secretly sends the emails to your laptop through Bluetooth whenever the phone is charging", "Your emails are saved on Google's cloud servers, so any device with your login can open them", "Gmail makes a hidden copy on every device you have ever used to sign in to the email service", "Your SIM card carries the emails wherever you go and shares them with any device you touch later"], ans: 1, why: "Gmail is a cloud app. Your emails sit on Google's big computers (servers) on the internet. Any device that signs in with your password sees the SAME inbox, because they are all looking at the same cloud copy. Bluetooth, SIM cards, and hidden device copies are not how it works.", bloom: "understand" },
    { q: "What is the main difference between saving a file in the cloud and saving it only on your laptop?", opts: ["Cloud files are always pictures while laptop files are always text documents saved in English", "Cloud files are always free and laptop files always cost money to save for your school assignments", "Cloud files work only in the morning and laptop files work only when it is dark outside at night", "Cloud files can be opened from many devices; laptop-only files live on one device and can be lost"], ans: 3, why: "A file saved only on your laptop stays on that one machine. If the laptop breaks or is lost, the file goes with it. A cloud file is kept safely on the internet — you can open it from any device, and it's still there even if your laptop dies. That is the main difference.", bloom: "understand" },
    { q: "A student loses her phone on the bus with 3 years of family photos on it. What would have kept her photos safe?", opts: ["Installing an anti-virus app on the phone to stop the photos from getting infected by viruses", "Turning on cloud backup (Google Photos or iCloud) so photos are also saved on the internet", "Keeping the phone in a hard plastic case so the photos inside would not get scratched on the bus", "Setting a strong screen-lock password so no one could open the phone after finding it on the seat"], ans: 1, why: "Anti-virus protects against malware, a case protects the hardware, a password protects privacy — none of them bring back a lost phone. Cloud backup means a second copy of every photo is saved on Google's or Apple's servers on the internet. New phone + sign in + all photos are back.", bloom: "apply" },
    { q: "You start writing a school project at home on your laptop. Tomorrow you need to finish it from your cousin's computer. What is the easiest way?", opts: ["Save it to Google Docs or OneDrive, then sign in on your cousin's computer and keep working", "Email the file to yourself again and again after every sentence you finish typing on the laptop", "Print the whole project, carry the papers, and retype everything from the start on the other computer", "Memorise the full project in your head and type it again from memory on your cousin's computer"], ans: 0, why: "Cloud apps like Google Docs, OneDrive, and Dropbox save your work on the internet as you type. Sign in from ANY computer and continue exactly where you stopped — no emailing, no retyping, no printing. This is one of the biggest everyday wins of the cloud for students.", bloom: "apply" },
    { q: "A class of 40 students wants to work on ONE shared document together at the same time. What is the best choice?", opts: ["One Word file shared through a USB stick that is passed around from desk to desk all period long", "A paper document that the students write on one after another during the whole class period", "A cloud document like Google Docs, where all 40 students can type in the same file together", "40 separate copies on 40 laptops, which the teacher will later combine into one file by hand"], ans: 2, why: "Google Docs is a cloud app. Many people can open the SAME file at the same time and see each other typing live. A USB stick works for one person at a time; paper and 40 separate copies waste time. Real-time shared editing is only possible because the file lives on the cloud.", bloom: "apply" },
    { q: "What is one real limitation of cloud storage that you should always remember?", opts: ["Cloud files become smaller every week and slowly disappear from your account if you do not open them often enough", "Cloud files only work on Apple devices — they cannot be opened on any Windows or Android phone", "Cloud files always take many hours to open even on a very fast and reliable internet connection", "If you have no internet connection, you cannot reach your cloud files until the internet works again"], ans: 3, why: "The cloud needs internet — no Wi-Fi or mobile data means no access to your files. Files do NOT shrink on their own, they work on every device (Android, Windows, Apple, Linux), and modern clouds open files in seconds. But internet is a real requirement: always keep an offline copy of anything critical.", bloom: "analyze" },
    { q: "Your friend says: \"Cloud is useless — you should save everything only on your own laptop, because then nobody else can ever see it.\" Evaluate this.", opts: ["Fully correct — the cloud is a scam and nobody who cares about their files should ever use any cloud app", "Not fully right — the cloud gives backup and easy sharing; a strong password keeps it private enough", "Fully wrong — laptops are obsolete and every person should delete every file from every laptop they own", "Partly right — but only because cloud apps usually delete your files by themselves after a week or so"], ans: 1, why: "A laptop-only file is private BUT risky — if the laptop breaks, the file is gone. The cloud is also private IF you use a strong password + 2-step sign-in. Best answer = both: keep important files on the cloud for backup and sharing, and keep a second copy on your device for offline work. Neither option is automatically 'always best'.", bloom: "evaluate" },
    { q: "Design a simple plan for a student so that school notes and projects are NEVER lost, even if the laptop breaks.", opts: ["Save every file only on the laptop and hope that the laptop will never break for the next four full years", "Print every single note and project and keep all the papers stacked on the student's desk at home only", "Save every file to Google Drive (or OneDrive), turn on phone photo backup, and keep one copy on the laptop", "Send every single note in a Telegram message to five different friends and ask them all to save it for you"], ans: 2, why: "The safe plan is 'cloud + device': main copy on the cloud (Google Drive or OneDrive) so it's reachable anywhere AND safe if the laptop dies; a second copy on the laptop for offline work; phone photos auto-backed to the cloud. Printing wastes paper and is hard to search. Asking friends is not secure and not reliable.", bloom: "create" },
  ],

  // ─── Topic 5: Blockchain (simple, school-level) ───
  5: [
    { q: "What is a blockchain, in simple words?", opts: ["A shared digital notebook copied across many computers, where nothing can be secretly changed", "A kind of mobile phone that was designed by a company called Bitcoin to replace older smartphones", "A large box that is kept in a bank basement so that money can be stored there very safely", "A game app where players collect digital coins by solving easy maths problems on the screen"], ans: 0, why: "Blockchain = a shared record copied across many computers. If someone tries to change one copy, all the others still show the original. It\u2019s not a phone, a bank box, or a game app.", bloom: "remember" },
    { q: "Is Bitcoin the same thing as blockchain?", opts: ["Yes \u2014 the two words mean exactly the same thing and can be used interchangeably in any sentence", "No \u2014 Bitcoin is one kind of money that runs on a blockchain; blockchain is the technology underneath", "Yes \u2014 blockchain is simply the older and slightly different name for the original Bitcoin system", "No \u2014 blockchain is a country where Bitcoin is the official national currency of every single business"], ans: 1, why: "Blockchain is the underlying technology. Bitcoin is just one example of money that runs on a blockchain. Other coins and many non-coin uses also run on blockchains.", bloom: "remember" },
    { q: "Why is it so hard to cheat a blockchain?", opts: ["Only one company owns the blockchain, and the workers there check every change by hand each day", "The blockchain is protected by a very large wall around a computer building near the capital city", "Many copies of the record exist across many computers, so changing one copy won\u2019t fool the others", "A single government passes a law every year that forbids any person from editing the records"], ans: 2, why: "Many copies live on many computers. If you change one, the others still show the truth \u2014 so the cheat is caught. It\u2019s not about walls, laws, or a single company.", bloom: "understand" },
    { q: "What does \u201cdecentralised\u201d mean in blockchain?", opts: ["The blockchain sits in the exact middle of a big building so everyone around can see it clearly", "It only works in countries where the national bank has officially been split into three smaller banks", "It was built at the physical centre of the earth, which is the most secure location anywhere known today", "No single company or government owns it \u2014 many computers together keep and check the records"], ans: 3, why: "Decentralised means no single owner. Many computers share the job of keeping and checking the records. It has nothing to do with buildings, countries, or the earth\u2019s centre.", bloom: "understand" },
    { q: "A chocolate company uses blockchain to track cocoa beans from farm to shop. Why is that useful?", opts: ["Because blockchain is the cheapest way to send a short message from one village to another village", "Because every step from farm to shop is recorded and the record cannot later be secretly changed", "Because the cocoa beans are physically placed inside the blockchain box for safer long transport", "Because the blockchain can turn raw cocoa beans into finished chocolate bars by itself in minutes"], ans: 1, why: "The value of blockchain here is a record of every step that cannot be secretly changed. It is not a messaging tool, a box, or a factory.", bloom: "apply" },
    { q: "A real estate company says: \u201cWith blockchain, property records can never be faked or lost.\u201d Is that the full story?", opts: ["Yes \u2014 blockchain completely solves every possible property problem anywhere in the world forever", "Yes \u2014 it is magic and once the record is on the chain no human mistake can ever happen anywhere", "Partly \u2014 the chain is hard to fake, but a human still has to type the right data in the first place", "No \u2014 blockchain is useless for any record and never makes anything more trustworthy than plain paper does"], ans: 2, why: "Blockchain protects the record from being changed later, but a human still has to enter correct info at the start. If the wrong name is typed, it will sit there forever. So the benefit is real but limited.", bloom: "apply" },
    { q: "A scammer in Telegram says: \u201cSend me some Bitcoin and I\u2019ll double it in 24 hours.\u201d Why is blockchain not really helping you here?", opts: ["Once you send the coins, the blockchain record cannot be reversed \u2014 so the scammer just keeps them", "Blockchain will automatically refund your money if you send it to any account you have never used", "The police can simply call the blockchain company and ask them to return all your coins to you quickly", "The scammer\u2019s wallet is locked by blockchain rules and the coins are returned to you in 24 hours as promised"], ans: 0, why: "Blockchain transactions are final \u2014 you can\u2019t \u201cundo\u201d a payment. There is no customer-service team to call. Scammers love this. Use blockchain carefully.", bloom: "apply" },
    { q: "Your cousin loses the password (\u201cprivate key\u201d) to his crypto wallet with 5,000,000 UZS of Bitcoin. What happens?", opts: ["The Bitcoin company will send him a new password by email after he proves his identity with a passport", "The police can unlock the wallet with a special law enforcement tool used for these unusual cases", "The bank will automatically refund the money to his UZ Card once he reports the loss to his branch", "The coins are most likely gone forever — without the key, no one can spend or move them again"], ans: 3, why: "A crypto wallet has no \u201cforgot password\u201d button and no central company. Lose the key = lose the coins. That is a key risk people must understand.", bloom: "analyze" },
    { q: "Your friend says: \u201cBlockchain is always a great idea \u2014 every company should use it for everything.\u201d Is this a good view?", opts: ["Yes \u2014 blockchain is faster and cheaper than normal databases for every kind of business in the whole world today", "Yes \u2014 blockchain solves every single computer problem a modern business could ever possibly have now", "Completely wrong \u2014 blockchain never works anywhere, and every company must stop using it immediately today", "No \u2014 blockchain fits where many parties must trust a shared record; for simple data, a normal database is fine"], ans: 3, why: "Blockchain shines when many people who don\u2019t fully trust each other need a shared, hard-to-change record. For a small shop\u2019s stock list, a normal database is simpler, cheaper, and faster.", bloom: "evaluate" },
    { q: "Design a sensible use of blockchain for Uzbekistan. Which idea uses blockchain for the RIGHT reason?", opts: ["Use blockchain for a student\u2019s daily to-do list on their phone because it is a new modern technology", "Use blockchain for a public record of land ownership so nobody can secretly change who owns a house", "Use blockchain to send a one-line good morning message to family on Telegram for a more modern feel", "Use blockchain as the colour theme on every government website in the country for a fresher style"], ans: 1, why: "Land records need to be tamper-proof and shared across many offices \u2014 exactly blockchain\u2019s strength. A to-do list, a Telegram message, and a colour theme don\u2019t need blockchain at all.", bloom: "create" },
  ],

  // ─── Topic 6: Virtual Reality (simple, school-level) ───
  6: [
    { q: "What is Virtual Reality (VR), in simple words?", opts: ["A computer-made world you step into using a headset that covers your eyes and replaces reality", "A phone filter that adds dog ears or glitter to your face when you take a selfie on Instagram", "A standard video game you play on a normal flat computer screen using a keyboard and mouse", "A clear pair of glasses that shows arrows above the real street while you walk around Tashkent"], ans: 0, why: "VR replaces reality. You wear a headset that shows a computer-made world. Filters, flat games, and clear \u201carrow\u201d glasses are other things (AR or normal games).", bloom: "remember" },
    { q: "What device do you normally need to use VR?", opts: ["A plastic table lamp that plugs into the wall socket and stands quietly next to your bed every single night", "A VR headset like Meta Quest or PlayStation VR that covers your eyes with small screens inside", "A regular pen and paper used for writing notes during long school lessons in the afternoon", "A paper map of Tashkent that shows every metro line and every main street in fine blue detail"], ans: 1, why: "A VR headset is the main device \u2014 it covers your eyes with screens showing the virtual world. A lamp, a pen, or a map are not VR devices.", bloom: "remember" },
    { q: "Why does VR feel much more \u201creal\u201d than watching the same scene on a flat TV screen?", opts: ["TVs are older technology and no TV in the world is able to show any modern 3D image at all", "Because the VR headset has a stronger battery that lasts much longer than a normal television does", "The headset covers your eyes and turns the scene as you turn your head, so you feel you are inside it", "They feel absolutely identical, with zero real difference between VR and watching TV at home in the evening"], ans: 2, why: "VR tracks your head. When you turn, the scene turns. Plus your real room disappears. Your brain starts to believe you\u2019re inside the scene \u2014 something a flat TV can\u2019t do.", bloom: "understand" },
    { q: "What is the biggest weakness of VR for tasks like walking around Tashkent or shopping at a bazaar?", opts: ["VR headsets are always more expensive than every single other kind of computer device in the world", "VR headsets do not work outdoors when the weather is sunny or when there is any bright sunlight around the user", "All VR headsets have much weaker graphics than normal TVs or phones for all users in every case", "VR blocks out the real world, so you can\u2019t see the street, the people, or the market stalls around you"], ans: 3, why: "VR covers your eyes \u2014 you can\u2019t see reality. Great for a game. Terrible for walking through Chorsu bazaar. Cost and weather aren\u2019t the main issue, and VR graphics are not always weaker.", bloom: "understand" },
    { q: "A medical school in Tashkent wants to let students practise surgery safely before touching a patient. Why does VR fit?", opts: ["VR costs much less money than the cheapest paper textbook sold by the university bookshop today at any price", "Students can practise surgery on a virtual patient many times with no risk and build real hand skills", "VR is the only tech used in any hospital anywhere in the world for every kind of medical training today", "Flat-screen tutorials are always stronger than VR for every possible medical subject a doctor may study"], ans: 1, why: "VR lets students repeat a procedure many times, from every angle, with no risk. That real practice builds skill before they touch a real patient. Cost and \u201conly tech used\u201d are not why it fits.", bloom: "apply" },
    { q: "A history teacher wants students to \u201cvisit\u201d Registan Square in Samarkand as it looked 500 years ago. Which tech fits best?", opts: ["Send every student on a long bus trip to modern Samarkand to see the Registan exactly as it looks today", "Hand out only printed postcards of the Registan photographed last year and let students sit in silence", "Tell the students to imagine the old Registan in their own minds without using any picture or any device", "A VR headset that shows a computer-made reconstruction of Registan Square as it looked 500 years ago"], ans: 3, why: "VR is perfect for places that do not exist anymore (old Registan). A bus trip only shows today. Postcards and imagination do not feel like being there.", bloom: "apply" },
    { q: "A parent is worried: \u201cMy child uses VR for 2 hours and then feels dizzy.\u201d What is one simple, sensible first step?", opts: ["Stop using all electronic devices forever and throw away every phone and every computer in the house", "Ignore the dizziness and keep using the VR headset for at least 3 or 4 hours each and every afternoon", "Buy a bigger and more expensive headset right away because only more costly headsets are fully safe", "Take short breaks every 15–20 minutes and sit down after using the headset to let the dizziness pass"], ans: 3, why: "VR dizziness is common with long sessions. Short breaks help most people. Throwing away all devices is extreme, ignoring the issue is dangerous, and spending more money doesn\u2019t fix it.", bloom: "apply" },
    { q: "Many users say they feel sick after 20 minutes of VR. What is a likely reason?", opts: ["The VR headset is always broken in some way and motion sickness is simply impossible to avoid", "Weak users imagine being sick and should train their bodies harder before using any VR headset at all", "Eyes see the VR world moving but the body feels still \u2014 this mismatch can make the brain feel dizzy", "VR never causes motion sickness \u2014 every single user always feels perfectly fine even after many hours"], ans: 2, why: "Your eyes see motion but your inner ear says \u201cyou\u2019re still.\u201d That mismatch confuses the brain \u2014 classic motion sickness. It\u2019s not weakness, not imagination, and not impossible to avoid.", bloom: "analyze" },
    { q: "A school director says: \u201cLet\u2019s replace ALL field trips with VR to save money.\u201d Evaluate the idea.", opts: ["Always replace \u2014 VR field trips are always exactly as good as going to a real place with your classmates", "Partly good \u2014 use VR for faraway or impossible places, but keep real trips for the social side too", "Never use VR in schools at any time for any reason, even when visiting a real place is impossible", "Only the budget matters \u2014 every school decision should be made by looking only at money saved and no other thing"], ans: 1, why: "VR is great for places you can\u2019t visit (Mars, old Samarkand). But real trips also teach social skills, teamwork, and real problem-solving. A mix is best.", bloom: "evaluate" },
    { q: "Design a short VR lesson for 14-year-olds about the inside of the human heart.", opts: ["Put students in VR to walk inside a giant heart, label the parts, and answer questions in-scene as they go", "Skip VR completely and make the students silently copy a whole textbook page about the human heart by hand", "Show a normal, non-interactive YouTube video about the heart inside the headset with no choices or tasks at all", "Let the students wear VR headsets for 45 minutes with no guidance and no task \u2014 just a random exploration"], ans: 0, why: "A good VR lesson uses VR\u2019s strengths: being INSIDE the heart, interacting, and answering short questions. Copying by hand ignores VR. A plain video in VR wastes the medium. Random use wastes the lesson time.", bloom: "create" },
  ],

  // ─── Topic 7: Augmented Reality (simple, school-level) ───
  7: [
    { q: "What is Augmented Reality (AR), in simple words?", opts: ["A headset that covers your eyes and fully replaces the real room with a computer-made new world", "A technology that adds digital things on top of the real world you see through your phone or glasses", "A video call app that lets family members in different Tashkent neighbourhoods speak to each other every day", "A very large library of printed maps showing every street, alley, and road in a country for careful study"], ans: 1, why: "AR adds digital content on top of the real world. The first option is VR. A video call app and paper maps are something else entirely.", bloom: "remember" },
    { q: "Which of these is the most common example of AR that ordinary people use every single day?", opts: ["A flat paper textbook read silently by a student at a desk during a history lesson at the university", "An email application running on a laptop with no camera and no 3D object or effect involved at all", "A VR headset used to play immersive first-person shooter games in the evening after finishing work", "Instagram and TikTok face filters that add dog ears or glitter to your face on the live camera"], ans: 3, why: "Instagram and TikTok filters are AR \u2014 they add digital effects on your real face. A textbook, a VR headset, and an email app are not AR.", bloom: "remember" },
    { q: "Why is AR often more practical than VR for walking around a real place like a bazaar?", opts: ["AR is cheaper than VR for every single user in every single country, with no exceptions anywhere in the whole world", "VR hardware simply does not work at all, while AR hardware is perfectly reliable all the time for every task", "AR and VR feel exactly the same in use \u2014 there is absolutely no meaningful difference between them in any way", "AR keeps the real world visible, so you can still see the stalls, the people, and where you are walking"], ans: 3, why: "AR keeps reality visible, so you can still walk around. VR blocks reality, which is dangerous in a busy bazaar. It\u2019s not about price or perfect hardware.", bloom: "understand" },
    { q: "You point your phone at your bedroom and the Uzum app shows a virtual sofa sitting in the corner. What\u2019s happening?", opts: ["The phone\u2019s camera and motion sensors work out the floor and then place the sofa image on the live view", "The app downloads a real sofa from Uzum\u2019s warehouse and delivers it silently through the phone\u2019s charging port", "It is a trick \u2014 nothing is being placed, the app just shows random sofa photos over a solid coloured background", "The app is connected to every home in Uzbekistan and uses your neighbour\u2019s living room layout to decide the spot"], ans: 0, why: "AR uses the camera and motion sensors to find flat surfaces and place a digital object at the right spot. No real delivery, no random photos, no neighbour connection.", bloom: "understand" },
    { q: "An Uzum product page uses AR to let you \u201cplace\u201d a fridge in your kitchen before buying. What problem does this solve?", opts: ["It delivers the fridge to your house instantly so you never need to wait for the shipping company at all", "It helps you see if the fridge will fit and look good in the real space, without using a measuring tape", "It records every purchase on the blockchain so nobody can ever change the details of the order once placed", "It magically discounts the price of the fridge by fifty percent just because you used the AR feature for a minute"], ans: 1, why: "AR here answers \u201cwill this fit and look right?\u201d without a tape measure. It does not deliver, use blockchain, or discount prices.", bloom: "apply" },
    { q: "A tourist app wants visitors to point their phones at Registan Square in Samarkand and see facts pop up over each building. Which tech fits?", opts: ["VR \u2014 every tourist must wear a full headset that completely hides the real square from view for best use", "Blockchain \u2014 the facts about each building are stored on a huge distributed ledger across many computers", "AR \u2014 digital labels and stories appear on top of the real live camera view of each building visible", "No technology fits this idea and tourists must keep buying printed paper guidebooks from Tashkent shops"], ans: 2, why: "Digital info on top of the real view = AR. VR would hide the real Registan, blockchain is for tamper-proof records, and paper guidebooks are not what the question asked for.", bloom: "apply" },
    { q: "A shop near Tashkent metro wants customers to \u201ctry on\u201d sunglasses using their phone camera before buying. Which tech is best?", opts: ["VR headsets for every single shopper, even though shoppers must still see the real shop around them at the same time", "Blockchain ledgers for each pair of sunglasses, copied across hundreds of computers before the customer tries them on", "No technology is suitable here, and customers must travel to several shops to try every pair one by one physically", "AR app that overlays a 3D pair of sunglasses on the customer\u2019s face through the front camera of the phone"], ans: 3, why: "Try-on over your real face via phone camera is AR. VR blocks reality, blockchain is about records, and \u201cno technology\u201d ignores a real product the shop wants to build.", bloom: "apply" },
    { q: "An AR museum guide shows digital labels floating over paintings, but users complain the labels shake and slide around. What is a likely cause?", opts: ["Users are imagining the problem \u2014 AR tracking never has any issue and every label is always perfectly placed", "AR is fundamentally broken and nothing can ever be done about it on any device released by any company", "The phone needs to see enough of the painting; fast movement or poor light confuse the tracking system", "The phone hardware is certainly damaged and must be replaced with a brand new model immediately by the user"], ans: 2, why: "AR relies on the camera seeing clear features. Fast movement, glare, or shadows break tracking and labels drift. It\u2019s not imagination, fundamental breakage, or always broken hardware.", bloom: "analyze" },
    { q: "A startup wants AR glasses that show the name and private details of every stranger you meet in Tashkent. Evaluate the idea.", opts: ["Every new tech idea should be built as quickly as possible without caring at all about privacy or legal or social issues", "Brilliant \u2014 every company should build and sell these glasses to every single person in every country straight away", "It would be impossible anyway \u2014 the AI needed for face recognition on strangers does not exist anywhere in the world yet", "Risky \u2014 scanning strangers without their permission raises serious privacy, legal, and trust problems for everyone"], ans: 3, why: "The biggest issue is not technical \u2014 it\u2019s consent and privacy. Strangers did not agree to be scanned. It\u2019s legally and socially risky, not \u201cbuild everything.\u201d", bloom: "evaluate" },
    { q: "Design a simple AR feature for a Tashkent clothing store to help customers choose the right size.", opts: ["A phone feature that lets customers try on a virtual t-shirt over themselves using the front camera in real time", "Remove all changing rooms from the shop and force every customer to guess the right size without any help at all", "Make the customer fill out a long, detailed paper form about body shape before they can buy a single t-shirt in the shop", "Replace every item with a VR headset experience where customers cannot see the real shop or the real clothes at all"], ans: 0, why: "An AR try-on is exactly what AR is good at \u2014 digital clothes on a real person. Removing changing rooms or making customers fill out forms is worse, and VR would hide the real shop.", bloom: "create" },
  ],

  // ─── Topic 8: Internet of Things (simple, school-level) ───
  8: [
    { q: "What is the Internet of Things (IoT), in simple words?", opts: ["A new kind of shopping website where people buy and sell physical things to each other every day", "Everyday objects connected to the internet so they can send data or be controlled from far away", "A very long, thick cable that runs under the city and joins every single house to the internet directly", "A type of phone game where you collect different digital objects called \u201cthings\u201d by tapping the screen quickly"], ans: 1, why: "IoT means everyday objects (lamp, watch, doorbell) connected to the internet. It\u2019s not a shopping site, a physical cable, or a game.", bloom: "remember" },
    { q: "Which of these is an example of an IoT device?", opts: ["A regular paper notebook with nothing but handwritten notes in ordinary blue or black ink on each page", "A smart watch that counts your daily steps and sends the numbers to the health app on your phone", "A plain wooden chair that stands in the living room and has no sensors, buttons, or computer inside", "A simple ballpoint pen you use to write your name on a school form during a Monday morning class"], ans: 1, why: "A smart watch senses (steps, heart rate), connects (Bluetooth), and sends data \u2014 that is IoT. A notebook, chair, and pen have no sensors or connection.", bloom: "remember" },
    { q: "What three things does most IoT do, in simple words?", opts: ["It prints a paper copy, posts it in the local mail, and then waits many days for the letter reply", "It grows taller every year, changes colour in every season, and then falls to the ground again at sunset", "It senses something, sends the info to the internet, and then something useful happens as a result", "It refuses to work without a strong sunny day, avoids every cloudy afternoon, and rests after any small rain"], ans: 2, why: "IoT senses \u2192 sends \u2192 acts. That simple loop fits smart watches, smart lamps, smart doorbells, and so on.", bloom: "understand" },
    { q: "What is the main difference between a smart lamp and a normal lamp?", opts: ["A normal lamp gives off strong yellow light while a smart lamp only gives off a weak dim blue light always", "A smart lamp is always heavier than any normal lamp because it has many small hidden coins inside it", "A smart lamp can be controlled from your phone and can turn on automatically using a timer or sensor", "A normal lamp always costs exactly one hundred times more money than any kind of smart lamp in every shop"], ans: 2, why: "A smart lamp is an IoT device \u2014 controlled from your phone or set on a timer. A normal lamp is just a switch. Colour, weight, and price aren\u2019t the defining difference.", bloom: "understand" },
    { q: "Your aunt wants to see who is at the gate of her house while she is at work in central Tashkent. Which IoT device fits?", opts: ["A smart doorbell with a camera that shows her a live video on her phone when someone is at the gate", "A thicker wooden front door with a larger handle and a much heavier lock built into the middle of it", "A louder metal bell mounted on the outside wall that will ring more loudly when a visitor arrives outside", "A paper note stuck on the gate asking every visitor to please come back later when the family is home"], ans: 0, why: "An IoT smart doorbell is exactly right \u2014 live camera, live video to the phone, two-way audio. Thicker doors, louder bells, or paper notes don\u2019t solve \u201cwho is at the gate right now.\u201d", bloom: "apply" },
    { q: "A Tashkent family wants their home AC to cool the house BEFORE they arrive home. Which IoT idea helps?", opts: ["Leave the AC switched on for the full day so that the rooms stay cold even when the house is empty", "Ignore the problem completely and just let everyone in the family wait an hour for the house to cool down", "Buy a second, bigger AC unit from Uzum and install it in a corner of the living room for stronger cooling", "Use a smart plug or smart AC that turns on from the phone 20 minutes before the family gets home"], ans: 3, why: "A smart AC or smart plug lets you turn things on from far away \u2014 saves power AND gives a cool house. Running all day wastes energy; a bigger AC doesn\u2019t solve remote control.", bloom: "apply" },
    { q: "A farmer near Samarkand wants to know when his fields need water. Which IoT setup fits best?", opts: ["Hire one full-time worker to walk around every field with a small wooden stick and poke the soil every few hours", "Put soil-moisture sensors in the fields that send numbers to the farmer\u2019s phone so he can water only when needed", "Stop watering the fields completely and hope the rain will fall at the exact right time for every single crop", "Cover the whole farm with a thick plastic sheet so the soil never loses any water to evaporation at any time"], ans: 1, why: "Soil sensors + phone notifications is a clean IoT idea: sense, send, act. Walking with a stick is slow, no water kills the crops, and plastic sheets ruin the farm.", bloom: "apply" },
    { q: "Many IoT devices are hacked because of ONE common mistake. Which one?", opts: ["The user forgets to change the default password, so anyone on the internet can easily log in to the device", "The user puts the device too near a window and sunlight damages the device\u2019s internal circuit boards over time", "The user places the device on a table that is too tall, which makes the Wi-Fi signal completely unreachable", "The user names the device in Uzbek, which makes it confusing for the router and the internet provider company"], ans: 0, why: "Default passwords are the #1 IoT security problem. Changing the password on setup stops most casual attacks. The other reasons aren\u2019t real security causes.", bloom: "analyze" },
    { q: "Your neighbour says: \u201cI will put a camera in every single room of my house for safety.\u201d Evaluate this idea.", opts: ["Always put as many cameras in every room as possible \u2014 privacy is not important as long as the house is safe", "Never install any camera anywhere in the world, even at the front gate when nobody is home at night", "Cameras are always totally safe and no hacker has ever been able to break into any home camera feed anywhere", "Risky \u2014 cameras near the gate can help, but cameras in bedrooms can leak very private family videos online"], ans: 3, why: "A few cameras near entry points are useful. Cameras in private rooms can leak family video if the account is hacked. Privacy matters too. \u201cAlways\u201d and \u201cnever\u201d are both too extreme.", bloom: "evaluate" },
    { q: "Design a simple IoT idea for a small Tashkent school that helps teachers without spying on students.", opts: ["Record every student\u2019s every word using microphones in every classroom and save it all to a server every day", "Track each student\u2019s exact location on school grounds all day with a personal GPS chip attached to each bag", "Use air-quality and temperature sensors to auto-open windows when CO2 is high in the classroom for fresher air", "Install a camera directly above every single desk and watch every student from above non-stop all day every day"], ans: 2, why: "Air-quality sensors help everyone (fresh air, fewer headaches) without spying on any individual. Recording voices, tracking locations, or watching every desk are privacy disasters.", bloom: "create" },
  ],

  // ─── Topic 9: Generative AI (simple, school-level) ───
  9: [
    { q: "What is Generative AI, in simple words?", opts: ["AI that can create new text, images, or videos when you ask it to with a short instruction", "A type of electricity generator used to power houses in Tashkent when the national grid has an outage", "A new kind of battery that never needs charging and can power a smartphone for an entire year at a time", "A very old style of computer program first built in the 1990s that is no longer used by anyone anywhere"], ans: 0, why: "Generative AI creates new content. It is not a power generator, a magic battery, or an old program.", bloom: "remember" },
    { q: "Which of these is an example of Generative AI?", opts: ["A calculator on your phone that adds two numbers when you type them on the on-screen keypad", "A paper notebook where you write your own poem in your own handwriting with your own blue pen", "ChatGPT writing a birthday message for your mum after you type a short request at night", "Your physical school bag holding all your books, pens, and lunch while you walk to class"], ans: 2, why: "ChatGPT creates new text \u2014 that is generative AI. A calculator is rules, a paper notebook is you, and a school bag isn\u2019t software.", bloom: "remember" },
    { q: "Why does ChatGPT sometimes give wrong answers with great confidence?", opts: ["OpenAI builds the wrong answers into the system deliberately to confuse the students of the world each day", "It doesn\u2019t know what is true \u2014 it just predicts the most likely next word, so it can write fluent lies", "ChatGPT is too old and has to be replaced by a brand new company every single year without exception", "ChatGPT only works when connected to a specific type of Wi-Fi router made in one country of the world"], ans: 1, why: "ChatGPT is a \u201cnext word predictor.\u201d It sounds confident even when wrong \u2014 that\u2019s called hallucination. Deliberate tricks, old code, or router brands are not the cause.", bloom: "understand" },
    { q: "What does \u201cGPT\u201d stand for in ChatGPT?", opts: ["Global Phone Tracker \u2014 a secret program that watches where every phone in a country is at every moment", "General Programming Tool \u2014 a piece of software used only by skilled engineers to build complex apps", "Generative Pre-trained Transformer \u2014 a type of AI model that generates text using deep learning patterns", "Good People\u2019s Technology \u2014 a brand-new type of smartphone released in Tashkent this year for young students"], ans: 2, why: "GPT = Generative Pre-trained Transformer. It\u2019s a type of AI. It is not a tracking program, a general tool, or a phone.", bloom: "understand" },
    { q: "A student is writing a short essay about climate change. What is a good way to use ChatGPT?", opts: ["Ask ChatGPT to write the full essay and submit it without changing a single word, then forget about the whole thing forever", "Use ChatGPT to explain the topic simply and brainstorm ideas, then write the essay in your own words and check facts", "Never use ChatGPT for anything, even just for making a lunch plan that is completely unrelated to the essay at all", "Ask ChatGPT to write the whole essay, change 3 or 4 words, and present the result as fully original personal work"], ans: 1, why: "AI as a study partner is fine: ideas, explanations, feedback. You still write and check. Submitting unchanged or near-identical AI text is cheating. A total ban ignores useful help.", bloom: "apply" },
    { q: "You ask an AI image app to draw \u201ca cat\u201d and it gives you a cat with six legs. Why did that happen?", opts: ["The developers of the app added this small joke on purpose just to make every single new user laugh at their own picture", "The app was trained only on pictures of dogs and was never shown a single picture of a real cat at any point", "The app is completely broken and no AI image app can ever draw any animal correctly under any condition", "The model learns what cats look like from lots of photos, but it does not really understand leg count or body parts"], ans: 3, why: "Image AI learns what \u201ccat\u201d pictures LOOK like without truly understanding anatomy. Extra legs are a known limitation. It\u2019s not a joke, total breakage, or dog-only training.", bloom: "apply" },
    { q: "A Tashkent student with good Uzbek but weak English wants help from ChatGPT. What is a fair way to use it?", opts: ["Paste your Uzbek text and let ChatGPT translate and rewrite the whole answer, then copy its exact English word for word without any change", "Use ChatGPT to help fix grammar and suggest clearer phrasing, but then you rewrite the idea in your own English words", "Never use any AI for any language help at all, because using AI always counts as full plagiarism in every class", "Let ChatGPT write the full essay in perfect English and change only the name at the top of the document to your own name"], ans: 1, why: "Grammar/clarity help is like a spell-checker. But copying full AI translations is plagiarism. A total ban punishes non-native speakers unfairly. Rewriting in YOUR own English is the fair middle.", bloom: "apply" },
    { q: "A news site fills its pages with AI-generated articles and slowly loses readers. What is a likely reason?", opts: ["The internet is always broken for news sites; this is unrelated to any content or AI choices by the news team", "Every reader in the world has suddenly stopped reading news content forever, and this applies to every single website equally too", "Readers cannot actually tell the difference between human and AI text, so the drop is purely a random coincidence", "AI articles often lack local details, specific names, and a real voice, so readers find them bland and stop visiting again"], ans: 3, why: "AI text sounds similar, misses local facts, and has no real voice. Readers notice and leave. The other options ignore what AI can and can\u2019t do well.", bloom: "analyze" },
    { q: "Your cousin says: \u201cChatGPT will write all my essays from now on \u2014 I don\u2019t need to learn to write anymore.\u201d Is this a good view?", opts: ["Yes \u2014 writing as a human skill is now completely obsolete and every student everywhere should stop learning it", "Yes \u2014 AI is always better than humans at every kind of writing task in every subject at every school ever", "Not a good view \u2014 writing is how we think clearly; people who can write AND use AI do better than either alone", "No \u2014 AI writing is always wrong, completely useless in every case, and no person should ever use it for any task"], ans: 2, why: "Writing teaches you to think. People who use AI wisely AND can write well beat both full-AI and full-manual. \u201cWriting is obsolete\u201d and \u201cAI is always wrong\u201d are both too extreme.", bloom: "evaluate" },
    { q: "Design a fair rule for your class on how ChatGPT may be used in homework.", opts: ["Ban ChatGPT completely and punish any student who even opens the ChatGPT app in the school building at any time", "Let every student copy and paste any ChatGPT answer directly into their homework without reading any of the text at all", "Do not write any rule and let every student in the class decide what counts as fair use for themselves each week", "Allow AI for brainstorming and polishing grammar, but the final text must be written by the student and AI use declared"], ans: 3, why: "The fair rule is a middle path: brainstorming/polishing OK, but you must write and declare AI use. Total bans and total freedom both fail.", bloom: "create" },
  ],

  // ─── Topic 10: Ethical Use of GPTs (simple, school-level) ───
  10: [
    { q: "What is an AI \u201challucination\u201d, in simple words?", opts: ["When the AI model physically overheats and starts showing strange characters on the laptop screen in the evening", "When the AI says something wrong with full confidence as if it were completely true and certain", "When the user dreams about the AI at night and cannot remember what the AI actually said the next morning", "When the AI completely stops answering for the whole day and does not respond to any question at all"], ans: 1, why: "A hallucination is when AI invents an answer and says it with confidence. It\u2019s not overheating, dreaming, or stopping.", bloom: "remember" },
    { q: "What is a \u201cdeepfake\u201d?", opts: ["A fake video or voice made by AI that shows a real person saying or doing things they never did", "A very old type of black-and-white photograph developed in a dark room using chemicals and paper", "A secret kind of Wi-Fi signal that only works deep inside basements and never reaches upper floors", "A very long fake social-media post written by a tired human worker during a quiet night-time shift"], ans: 0, why: "Deepfakes are AI-made fake videos or voice clips of real people. They are not old photos, a Wi-Fi signal, or plain human text.", bloom: "remember" },
    { q: "Why can AI be unfair to certain groups of people, even if no one programmed it to be unfair?", opts: ["All AI developers in the world secretly hate specific groups of people and plan the unfairness from day one", "The AI learns from past data, and if the past was unfair, the AI copies that unfair pattern in its answers", "AI is always perfectly fair by design, so the users must have made a mistake when entering the information", "Every new AI tool is the same, and they all fix every kind of unfairness completely on the first day of use"], ans: 1, why: "AI learns from past data. If the past was unfair, the AI repeats the unfairness. It\u2019s not a secret plan, a user error, or an auto-fix.", bloom: "understand" },
    { q: "Why is submitting an essay fully written by ChatGPT usually called plagiarism?", opts: ["Because ChatGPT secretly puts a hidden watermark in every text and the teachers always find it automatically straight away", "Because OpenAI sues every student who uses any ChatGPT text for any school project or university assignment", "Because you are presenting someone else\u2019s work as your own, and the assignment is meant to test YOUR thinking", "Because every plagiarism checker in the world can find AI text with 100% accuracy in every single real case"], ans: 2, why: "Plagiarism means presenting other work as your own. Submitting ChatGPT\u2019s words as yours hides who actually did the thinking. Watermarks and lawsuits are not the main reason.", bloom: "understand" },
    { q: "Student A uses ChatGPT to explain a hard topic and then writes the essay in her own words. Student B copies ChatGPT\u2019s answer and changes 2 words. Who is cheating?", opts: ["Only B is cheating \u2014 A used AI as a learning helper; B passed off AI\u2019s text as her own work almost unchanged", "Both are cheating, because any student who even looks at an AI tool automatically fails every assignment from now on", "Neither is cheating, because every form of AI use is always 100% fine in every school and university worldwide at any time", "Only A is cheating because looking at ChatGPT first always gives an unfair advantage in writing the final essay"], ans: 0, why: "Student A uses AI like a tutor. Student B hands in AI text as hers \u2014 plagiarism. Looking at AI isn\u2019t the crime; pretending it\u2019s your work is.", bloom: "apply" },
    { q: "Your cousin wants to type his very private health problems into a free chatbot to get advice. What should he think about first?", opts: ["Share every single personal detail freely, because every chatbot is always completely private in every country in the world", "Skip chatbots forever and also avoid doctors completely, even when he is very unwell and his symptoms keep getting worse", "Type everything and also send the same details to ten random strangers on Telegram just in case it helps his search", "Assume that anything he types may be saved on a server, and decide what to share based on that risk before typing"], ans: 3, why: "Chatbot messages can be logged. Don\u2019t share what you wouldn\u2019t show a stranger. A total ban on doctors is harmful, and sharing with random strangers is worse.", bloom: "apply" },
    { q: "You see a shocking video of a local politician on Telegram that may be a deepfake. What is a sensible first step before sharing?", opts: ["Forward it to every family group chat right now because viral forwards are always a great way to help the truth win", "Delete the app completely and also delete every news app from the phone just to avoid seeing any political content later", "Check a few trusted news websites and the politician\u2019s official accounts to see if the video is reported there too", "Assume every single video ever posted online is automatically a deepfake and never trust any video from any source again"], ans: 2, why: "Before sharing, check the video with trusted news sources. Forwarding unchecked videos spreads misinformation. Extreme \u201cdelete everything\u201d or \u201ctrust nothing\u201d aren\u2019t sensible.", bloom: "apply" },
    { q: "A bank in Tashkent uses an AI to decide who gets a loan. It approves far fewer people from one neighbourhood. The AI was trained on old loan records. Where did the unfairness come from?", opts: ["The software engineers secretly added the unfair rule to the code because they personally dislike that neighbourhood for no reason", "The old loan records already favoured some neighbourhoods, so the AI learned and repeated the same unfair pattern", "The AI\u2019s computer hardware is damaged and produces wrong answers whenever the room temperature is too warm or too cold", "Residents of that neighbourhood always type their name wrong on the application form, which blocks their loan every time"], ans: 1, why: "Bias usually comes from biased training data. Not from secret coders, broken hardware, or typing errors.", bloom: "analyze" },
    { q: "A startup wants to create fake videos of a rival company\u2019s CEO saying false things. Evaluate the idea.", opts: ["Completely fine, because deepfakes are very modern technology and any modern technology is always legal and ethical in every country", "It is an excellent marketing plan, and every company should make deepfakes of every rival to win in a tough market", "Very bad \u2014 it is fraud and defamation, it harms a real person, and it damages people\u2019s trust in every real video forever", "It might be okay only inside one country, and most companies around the world can safely do this kind of thing at any time"], ans: 2, why: "Fake videos of real people are fraud and defamation. They hurt one person and break trust in all real video evidence. Not a good plan.", bloom: "evaluate" },
    { q: "Design a short, practical checklist that a student can run through before using ChatGPT for a serious task.", opts: ["Skip the check entirely and just paste anything you have into the chatbot without stopping to think for a single second", "Never use any AI tool for anything ever, even when a teacher has clearly said that polite and honest use is allowed today", "Use AI freely, without ever checking facts, because AI is always perfectly correct in every subject on every single day of the year", "Ask: is the fact checked? is my private info safe? have I said I used AI? does the teacher allow it? am I still thinking?"], ans: 3, why: "A good checklist: check facts, protect privacy, disclose AI use, follow the rules, keep thinking. Skipping checks or never using AI aren\u2019t balanced answers.", bloom: "create" },
  ],
};
